def merge_identities(records: list[list[str]]) -> list[list[str]]:
    parent = list(range(len(records)))

    def find(x: int) -> int:
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra != rb:
            # The smaller index becomes the root: it is the earliest record.
            parent[max(ra, rb)] = min(ra, rb)

    owner: dict[str, int] = {}
    for i, record in enumerate(records):
        for email in record[1:]:
            email = email.lower()
            if email in owner:
                union(i, owner[email])
            else:
                owner[email] = i

    emails: dict[int, set[str]] = {}
    for i, record in enumerate(records):
        group = emails.setdefault(find(i), set())
        group.update(e.lower() for e in record[1:])
    return [[records[root][0], *sorted(group)] for root, group in sorted(emails.items())]
